 for(const[d,port,ip]of [[r1,'GigabitEthernet0/0','192.168.10.1'],[r1,'GigabitEthernet0/1','192.168.20.1'],[srv1,p,'192.168.20.10'],[srv2,p,'192.168.10.50'],[pc3,p,'192.168.10.60']]as const){Object.assign(d.config.interfaces[port],{ip,mask:'255.255.255.0',adminUp:true});d.config.interfaces[port].features.dhcp=false;}
 srv1.config.defaultGateway='192.168.20.1';srv2.config.defaultGateway=pc3.config.defaultGateway='192.168.10.1';srv2.config.interfaces[p].features.macAddress=DAI_STATIC_MAC;
 r1.config.services.dhcp={enabled:true,pools:[{name:'USERS',network:'192.168.10.0',prefix:24,defaultRouter:'192.168.10.1',dnsServers:['192.168.20.10'],leaseSeconds:3600}],excluded:[{start:'192.168.10.1',end:'192.168.10.99'},{start:'192.168.10.150',end:'192.168.10.254'}]};
 srv1.config.services.dns={enabled:true,resourceRecords:[{name:'server.dai.lab',type:'A',value:'192.168.20.10',ttl:300}]};for(const d of [srv1,srv2])d.config.services.http={enabled:true,port:80,authentication:'none',content:'<!doctype html><html lang="en"><meta charset="utf-8"><title>'+d.config.hostname+'</title><h1>'+d.config.hostname+': ARP-protected service reached</h1></html>'};
 sw.config.vlans[10]={id:10,name:'USERS',active:true};for(const n of [1,2,3,4,5]){const port=sw.config.interfaces['GigabitEthernet0/'+n];Object.assign(port,{mode:'access',vlan:10,adminUp:true});port.features.portfast=true;}
