 lap.config.defaultGateway='192.168.100.1';lap.config.features.users={archive:{secret:'SftpLab123',privilege:1}};lap.config.services.sshFiles={enabled:true,readOnly:false,files:{'sftp-readme.txt':'NetworkSim SFTP reference file.\nText backup endpoint: PC1.\n'}};
