 for(const[i,r]of routers.entries()){address(r,0,`192.168.${(i+1)*10}.1`,'255.255.255.0','PASSIVE_LAN');const h=hosts[i];Object.assign(h.config.interfaces.GigabitEthernet0,{ip:`192.168.${(i+1)*10}.10`,mask:'255.255.255.0'});h.config.interfaces.GigabitEthernet0.features.dhcp=false;h.config.defaultGateway=`192.168.${(i+1)*10}.1`;}
