 const make=(name:string,kind:Device['kind'],x:number,y:number):Device=>({id:'device-host-route-'+name.toLowerCase(),kind,x,y,powered:true,config:factoryDeviceConfig(kind,name),runtime:emptyRuntime()});
 const r1=make('R1','router',350,250),r2=make('R2','router',750,150),r3=make('R3','router',750,500),pc=make('PC1','pc',100,250),sw=make('SW1','switch',750,730),server1=make('SRV1','server',530,930),server2=make('SRV2','server',970,930),routers=[r1,r2,r3];
