 address(r1,1,'10.0.12.1','255.255.255.252','2001:db8:12::1','fe80::1','TO_R2');address(r2,1,'10.0.12.2','255.255.255.252','2001:db8:12::2','fe80::2','TO_R1');address(r2,2,'10.0.23.1','255.255.255.252','2001:db8:23::2','fe80::2','TO_R3');address(r3,1,'10.0.23.2','255.255.255.252','2001:db8:23::3','fe80::3','TO_R2');address(r1,2,'10.0.13.1','255.255.255.252','2001:db8:13::1','fe80::1','DIRECT_TO_R3');address(r3,2,'10.0.13.2','255.255.255.252','2001:db8:13::3','fe80::3','DIRECT_TO_R1');
 r2.config.staticRoutes=[{network:'192.168.10.0',prefix:24,nextHop:'10.0.12.1',ad:1},{network:'203.0.113.0',prefix:24,nextHop:'10.0.23.2',ad:1},{network:'2001:db8:10::',prefix:64,nextHop:'2001:db8:12::1',ad:1},{network:'2001:db8:30::',prefix:64,nextHop:'2001:db8:23::3',ad:1}];
 for(const[d,ip,ipv6,gateway,ll]of [[pc,'192.168.10.10','2001:db8:10::10','192.168.10.1','fe80::1'],[server1,'203.0.113.10','2001:db8:30::10','203.0.113.1','fe80::3'],[server2,'203.0.113.20','2001:db8:30::20','203.0.113.1','fe80::3']] as const){const p=d.config.interfaces.GigabitEthernet0;Object.assign(p,{ip,mask:'255.255.255.0',ipv6:[ipv6+'/64']});Object.assign(p.features,{dhcp:false,ipv6Autoconfig:false});d.config.defaultGateway=gateway;d.config.staticRoutes=[{network:'::',prefix:0,nextHop:ll,interface:'GigabitEthernet0',ad:1}];}
