 const protection:Criterion={kind:'all',criteria:[23,24].flatMap(n=>[setting(n,'adminUp',true),setting(n,'loopGuard',true),setting(n,'rootGuard',false),setting(n,'bpduguard',false),setting(n,'portfast',false),setting(n,'mode','trunk'),setting(n,'nativeVlan',99),{kind:'trunk-allowed',device:sw3.id,interface:g(n),vlans:[10,99]}])};
