 for(const sw of switches){sw.config.features.stp={mode:'pvst',vlanPriorities:{10:32768,20:32768}};for(const[id,name]of [[10,'USERS'],[20,'GUESTS'],[99,'NATIVE']]as const)sw.config.vlans[id]={id,name,active:true};for(const n of [23,24]){const port=sw.config.interfaces[`GigabitEthernet0/${n}`];Object.assign(port,{mode:'trunk',nativeVlan:99,allowedVlans:[10,20,99],adminUp:false});port.features.nonegotiate=true;port.features.portfast=false;}}
