 for(const[pc,sw,n,vlan,address]of endpoints){const port=sw.config.interfaces[`GigabitEthernet0/${n}`];Object.assign(port,{mode:'access',vlan,description:'TO_'+pc.config.hostname});port.features.portfast=false;Object.assign(pc.config.interfaces.GigabitEthernet0,{ip:address,mask:'255.255.255.0'});pc.config.interfaces.GigabitEthernet0.features.dhcp=false;pc.config.defaultGateway=undefined;}
