 switches[0].config.interfaces[g(23)].adminUp=false;switches[0].config.interfaces[g(24)].nativeVlan=1;
 const remote=switches[1];remote.config.interfaces[g(24)].features.channelGroup=2;remote.config.interfaces[po].adminUp=false;for(const p of [po,...members])remote.config.interfaces[p].allowedVlans=[10,99];remote.config.interfaces['Port-channel2']={...structuredClone(remote.config.interfaces[po]),name:'Port-channel2',adminUp:true};
 for(const d of lab.devices)d.startupConfig=structuredClone(d.config);
 const property=(sw:Device,p:string,property:Extract<Criterion,{kind:'interface'}>['property'],value:string|number|boolean):Criterion=>({kind:'interface',device:sw.id,interface:p,property,value});
 const modes:Criterion={kind:'all',criteria:switches.flatMap((sw,i)=>members.map(p=>property(sw,p,'channelMode',i?'passive':'active')))};
 const groups:Criterion={kind:'all',criteria:switches.flatMap(sw=>members.flatMap(p=>[property(sw,p,'channelGroup',1),property(sw,p,'switchport',true)]))};
 const consistent:Criterion={kind:'all',criteria:switches.flatMap(sw=>[po,...members].flatMap(p=>[property(sw,p,'mode','trunk'),property(sw,p,'nativeVlan',99),property(sw,p,'portfast',false)]))};
 const enabled:Criterion={kind:'all',criteria:switches.flatMap(sw=>members.map(p=>property(sw,p,'adminUp',true)))};
 const logical:Criterion={kind:'all',criteria:switches.flatMap(sw=>[property(sw,po,'adminUp',true),property(sw,po,'switchport',true)])};
