 for(const sw of switches){for(const[id,name]of [[10,'USERS'],[20,'GUESTS'],[99,'NATIVE']] as const)sw.config.vlans[id]={id,name,active:true};for(const[n,vlan]of [[1,10],[2,20]]){const p=sw.config.interfaces[`GigabitEthernet0/${n}`];Object.assign(p,{mode:'access',vlan});p.features.portfast=true;}for(const n of [23,24])sw.config.interfaces[`GigabitEthernet0/${n}`].adminUp=false;}
